#!/usr/bin/env python3
"""Offline SIP identity boundary processor.

Implements the deterministic batch protocol described in PROTOCOL.md
(revision 1): parse and validate untrusted SIP request text, resolve
identity claims strictly through the supplied directory, apply the
ingress authorization policy of the receiving gateway, and emit the
canonical forwarded wire text for accepted requests.

Standard library only.  Reads one JSON object on stdin, writes one JSON
object on stdout.
"""

import json
import re
import sys

# --------------------------------------------------------------------------
# Protocol constants
# --------------------------------------------------------------------------

ANON = "sip:anonymous@anonymous.invalid"
MAX_TEXT = 32768
MAX_PHYS_LINES = 512
MAX_LOGICAL_FIELDS = 128
CSEQ_MAX = 2147483647

METHODS = ("INVITE", "MESSAGE")

_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
_DIGITS = "0123456789"

ALNUM = frozenset(_LETTERS + _DIGITS)
TOKEN_CHARS = frozenset(_LETTERS + _DIGITS + "-.!%*_+`'~")
USER_CHARS = frozenset(_LETTERS + _DIGITS + "-_.!~*'()+")
HEXDIG = frozenset(_DIGITS + "ABCDEFabcdef")
WS = " \t"
# Characters that terminate a URI token inside a header value.
URI_STOP = frozenset(" \t<>,;")

CALLID_RE = re.compile(r"[A-Za-z0-9_.@+-]{1,128}\Z")
HEADER_RE = re.compile(r"([-A-Za-z0-9.!%*_+`'~]+)[ \t]*:(.*)\Z")

COMPACT = {
    "f": "from",
    "t": "to",
    "i": "call-id",
    "l": "content-length",
    "c": "content-type",
}

REQUIRED = ("from", "to", "call-id", "cseq", "content-length")
SINGLETON = ("p-preferred-identity", "remote-party-id", "privacy", "content-type")


class Reject(Exception):
    """A deterministic protocol rejection."""

    __slots__ = ("reason",)

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


def syntax():
    raise Reject("syntax")


# --------------------------------------------------------------------------
# Character level helpers
# --------------------------------------------------------------------------

def check_head_chars(line):
    """Header section lines: printable ASCII plus HTAB only."""
    for ch in line:
        o = ord(ch)
        if o != 9 and not (32 <= o <= 126):
            syntax()


def check_body_chars(body):
    """Body: printable ASCII, HTAB, CR and LF only."""
    for ch in body:
        o = ord(ch)
        if o == 9 or o == 10 or o == 13:
            continue
        if not (32 <= o <= 126):
            syntax()


def skip_ws(value, index):
    n = len(value)
    while index < n and value[index] in WS:
        index += 1
    return index


def strip_ws(value):
    return value.strip(" \t")


# --------------------------------------------------------------------------
# URI grammar and normalization
# --------------------------------------------------------------------------

def normalize_user(text):
    if not text:
        syntax()
    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == "%":
            if i + 2 >= n:
                syntax()
            hi = text[i + 1]
            lo = text[i + 2]
            if hi not in HEXDIG or lo not in HEXDIG:
                syntax()
            decoded = chr(int(hi + lo, 16))
            if decoded not in USER_CHARS:
                syntax()
            out.append(decoded)
            i += 3
        elif ch in USER_CHARS:
            out.append(ch)
            i += 1
        else:
            syntax()
    return "".join(out)


def normalize_host(text):
    if not text:
        syntax()
    if "%" in text:
        syntax()
    if text.endswith("."):
        text = text[:-1]
    if not text or text.endswith("."):
        syntax()
    if len(text) > 253:
        syntax()
    for label in text.split("."):
        ln = len(label)
        if ln < 1 or ln > 63:
            syntax()
        if label[0] not in ALNUM or label[-1] not in ALNUM:
            syntax()
        for ch in label:
            if ch != "-" and ch not in ALNUM:
                syntax()
    return text.lower()


def normalize_tel(rest):
    if not rest.startswith("+"):
        syntax()
    digits = rest[1:]
    ln = len(digits)
    if ln < 1 or ln > 15:
        syntax()
    for ch in digits:
        if ch not in _DIGITS:
            syntax()
    if digits[0] == "0":
        syntax()
    return "tel:" + "+" + digits


def parse_uri(candidate):
    """Validate and lexically normalize one URI candidate.

    Returns (normalized_uri, scheme).  Raises Reject('syntax') otherwise.
    """
    if not candidate:
        syntax()
    prefix = candidate[:4].lower()
    if prefix == "sip:":
        rest = candidate[4:]
        at = rest.find("@")
        if at < 0:
            syntax()
        user = rest[:at]
        host = rest[at + 1:]
        if "@" in host:
            syntax()
        return "sip:" + normalize_user(user) + "@" + normalize_host(host), "sip"
    if prefix == "tel:":
        return normalize_tel(candidate[4:]), "tel"
    syntax()


def scan_uri(value, index):
    """Consume the maximal non-delimiter run at index and parse it as a URI."""
    n = len(value)
    j = index
    while j < n and value[j] not in URI_STOP:
        j += 1
    if j == index:
        syntax()
    uri, scheme = parse_uri(value[index:j])
    return uri, scheme, j


# --------------------------------------------------------------------------
# Display names, quoted strings and addresses
# --------------------------------------------------------------------------

def scan_quoted(value, index):
    """value[index] must be a double quote.  Return the index after it."""
    n = len(value)
    i = index + 1
    while True:
        if i >= n:
            syntax()
        ch = value[i]
        if ch == "\\":
            if i + 1 >= n:
                syntax()
            nxt = value[i + 1]
            o = ord(nxt)
            if o != 9 and not (32 <= o <= 126):
                syntax()
            i += 2
            continue
        if ch == '"':
            return i + 1
        i += 1


def find_angle(value, index):
    """First '<' outside a quoted string, or None.  Validates quoted strings."""
    n = len(value)
    i = index
    while i < n:
        ch = value[i]
        if ch == "<":
            return i
        if ch == '"':
            i = scan_quoted(value, i)
            continue
        i += 1
    return None


def validate_display(text):
    """A display-name is a quoted string or a run of whitespace separated tokens."""
    if not text:
        syntax()
    if text[0] == '"':
        end = scan_quoted(text, 0)
        if strip_ws(text[end:]):
            syntax()
        return
    parts = text.split()
    if not parts:
        syntax()
    for part in parts:
        for ch in part:
            if ch not in TOKEN_CHARS:
                syntax()


def parse_address(value, index, allow_tag):
    """Parse one address at value[index:].

    Returns (uri, scheme, tag, next_index).
    """
    n = len(value)
    index = skip_ws(value, index)
    if index >= n:
        syntax()
    tag = None
    if value[index] == "<":
        j = skip_ws(value, index + 1)
        uri, scheme, j = scan_uri(value, j)
        j = skip_ws(value, j)
        if j >= n or value[j] != ">":
            syntax()
        j += 1
    else:
        angle = find_angle(value, index)
        if angle is None:
            uri, scheme, j = scan_uri(value, index)
        else:
            validate_display(value[index:angle])
            j = skip_ws(value, angle + 1)
            uri, scheme, j = scan_uri(value, j)
            j = skip_ws(value, j)
            if j >= n or value[j] != ">":
                syntax()
            j += 1
    if not allow_tag:
        return uri, scheme, None, j
    k = skip_ws(value, j)
    if k < n and value[k] == ";":
        k = skip_ws(value, k + 1)
        start = k
        while k < n and value[k] in TOKEN_CHARS:
            k += 1
        if value[start:k].lower() != "tag":
            syntax()
        k = skip_ws(value, k)
        if k >= n or value[k] != "=":
            syntax()
        k = skip_ws(value, k + 1)
        start = k
        while k < n and value[k] in TOKEN_CHARS:
            k += 1
        tag = value[start:k]
        if not tag or len(tag) > 128:
            syntax()
        k = skip_ws(value, k)
        j = k
    else:
        j = k
    return uri, scheme, tag, j


def parse_single(value, allow_tag):
    """Exactly one address and nothing else."""
    uri, scheme, tag, index = parse_address(value, 0, allow_tag)
    index = skip_ws(value, index)
    if index != len(value):
        syntax()
    return uri, scheme, tag


def parse_list(value):
    """A comma separated address list with no header parameters."""
    out = []
    n = len(value)
    i = 0
    while True:
        i = skip_ws(value, i)
        if i >= n:
            syntax()
        uri, scheme, _tag, i = parse_address(value, i, False)
        out.append((uri, scheme))
        i = skip_ws(value, i)
        if i >= n:
            return out
        if value[i] == ",":
            i += 1
            continue
        syntax()


# --------------------------------------------------------------------------
# Header field value validation
# --------------------------------------------------------------------------

def parse_callid(value):
    if not CALLID_RE.match(value):
        syntax()
    return value


def parse_cseq(value, method):
    i = 0
    n = len(value)
    while i < n and value[i] in _DIGITS:
        i += 1
    if i == 0:
        syntax()
    digits = value[:i]
    j = skip_ws(value, i)
    if j == i:
        syntax()
    if value[j:] != method:
        syntax()
    if len(digits) > 10:
        syntax()
    number = int(digits)
    if number < 1 or number > CSEQ_MAX:
        syntax()
    return number


def parse_content_length(value, body_length):
    if not value:
        syntax()
    for ch in value:
        if ch not in _DIGITS:
            syntax()
    digits = value.lstrip("0") or "0"
    if digits != str(body_length):
        syntax()
    return body_length


def parse_content_type(value):
    if not value:
        syntax()
    for ch in value:
        o = ord(ch)
        if o != 9 and not (32 <= o <= 126):
            syntax()
    return value


def parse_privacy(value):
    lowered = value.lower()
    if lowered not in ("id", "none"):
        syntax()
    return lowered


# --------------------------------------------------------------------------
# Request parsing
# --------------------------------------------------------------------------

class Request(object):
    __slots__ = ("method", "ruri", "from_uri", "from_tag", "to_uri", "to_tag",
                 "callid", "cseq", "ctype", "privacy", "pai", "ppi", "rpid",
                 "body")


def parse_request(text):
    if len(text) > MAX_TEXT:
        syntax()
    split = text.find("\r\n\r\n")
    if split < 0:
        syntax()
    head = text[:split]
    body = text[split + 4:]
    check_body_chars(body)

    lines = head.split("\r\n")
    for line in lines:
        if "\r" in line or "\n" in line:
            syntax()
        check_head_chars(line)
    if len(lines) - 1 > MAX_PHYS_LINES:
        syntax()

    request_line = lines[0]
    parts = request_line.split(" ")
    if len(parts) != 3:
        syntax()
    method, raw_ruri, version = parts
    if method not in METHODS:
        syntax()
    if version != "SIP/2.0":
        syntax()
    ruri, ruri_scheme = parse_uri(raw_ruri)
    if ruri_scheme != "sip":
        syntax()

    fields = []
    for line in lines[1:]:
        if line and line[0] in WS:
            if not fields:
                syntax()
            name, value = fields[-1]
            fields[-1] = (name, value + " " + line.lstrip(" \t"))
            continue
        match = HEADER_RE.match(line)
        if match is None:
            syntax()
        fields.append((match.group(1).lower(), match.group(2)))
        if len(fields) > MAX_LOGICAL_FIELDS:
            syntax()

    grouped = {}
    order = []
    for name, value in fields:
        name = COMPACT.get(name, name)
        if name not in grouped:
            grouped[name] = []
            order.append(name)
        grouped[name].append(strip_ws(value))

    for name in REQUIRED:
        if len(grouped.get(name, ())) != 1:
            syntax()
    for name in SINGLETON:
        if len(grouped.get(name, ())) > 1:
            syntax()

    req = Request()
    req.method = method
    req.ruri = ruri
    req.body = body

    from_uri, from_scheme, from_tag = parse_single(grouped["from"][0], True)
    to_uri, to_scheme, to_tag = parse_single(grouped["to"][0], True)
    req.from_uri = from_uri
    req.from_tag = from_tag
    req.to_uri = to_uri
    req.to_tag = to_tag

    req.callid = parse_callid(grouped["call-id"][0])
    req.cseq = parse_cseq(grouped["cseq"][0], method)
    req.ctype = None
    if "content-type" in grouped:
        req.ctype = parse_content_type(grouped["content-type"][0])
    parse_content_length(grouped["content-length"][0], len(body))

    req.privacy = None
    if "privacy" in grouped:
        req.privacy = parse_privacy(grouped["privacy"][0])

    req.ppi = None
    if "p-preferred-identity" in grouped:
        uri, _scheme, _tag = parse_single(grouped["p-preferred-identity"][0], False)
        if uri == ANON:
            syntax()
        req.ppi = uri

    req.rpid = None
    if "remote-party-id" in grouped:
        uri, _scheme, _tag = parse_single(grouped["remote-party-id"][0], False)
        if uri == ANON:
            syntax()
        req.rpid = uri

    pai = []
    for value in grouped.get("p-asserted-identity", ()):
        pai.extend(parse_list(value))
    if pai:
        if len(pai) > 2:
            syntax()
        for uri, _scheme in pai:
            if uri == ANON:
                syntax()
        if len(pai) == 2 and pai[0][1] == pai[1][1]:
            syntax()
    req.pai = [uri for uri, _scheme in pai]
    return req


# --------------------------------------------------------------------------
# Wire serialization
# --------------------------------------------------------------------------

def build_wire(req, selected, private, emit_pai):
    from_uri = ANON if private else selected
    lines = [req.method + " " + req.ruri + " SIP/2.0"]
    head = "<" + from_uri + ">"
    if req.from_tag is not None:
        head += ";tag=" + req.from_tag
    lines.append("From: " + head)
    head = "<" + req.to_uri + ">"
    if req.to_tag is not None:
        head += ";tag=" + req.to_tag
    lines.append("To: " + head)
    lines.append("Call-ID: " + req.callid)
    lines.append("CSeq: " + str(req.cseq) + " " + req.method)
    lines.append("Privacy: " + ("id" if private else "none"))
    if emit_pai:
        lines.append("P-Asserted-Identity: <" + selected + ">")
    if req.ctype is not None:
        lines.append("Content-Type: " + req.ctype)
    lines.append("Content-Length: " + str(len(req.body)))
    return "\r\n".join(lines) + "\r\n\r\n" + req.body


# --------------------------------------------------------------------------
# Policy
# --------------------------------------------------------------------------

class Policy(object):
    def __init__(self, directory, accounts, gateways):
        self.alias = {}
        for canonical, aliases in directory.items():
            self.alias[canonical] = canonical
            for item in aliases:
                self.alias[item] = canonical
        self.domain = {}
        for canonical in directory:
            at = canonical.find("@")
            self.domain[canonical] = canonical[at + 1:] if at >= 0 else None
        self.accounts = accounts
        self.gateways = gateways

    def resolve(self, claim):
        return self.alias.get(claim)

    def hosted(self, gateway, identity):
        domain = self.domain.get(identity)
        if domain is None:
            return False
        return domain in self.gateways[gateway]["local_domains"]

    def allowed(self, subject, identity):
        account = self.accounts[subject]
        if identity == account["primary"]:
            return True
        return identity in account["allow"]

    def peer_domains(self, gateway, peer):
        return self.gateways[gateway]["peers"][peer]


def decide_local(req, policy, gateway, subject):
    if subject not in policy.accounts:
        raise Reject("unauthenticated")
    claims = []
    if req.from_uri != ANON:
        claims.append(req.from_uri)
    if req.ppi is not None:
        claims.append(req.ppi)
    resolved = {}
    for claim in claims:
        identity = policy.resolve(claim)
        if identity is None:
            raise Reject("identity")
        if not policy.allowed(subject, identity):
            raise Reject("identity")
        if not policy.hosted(gateway, identity):
            raise Reject("identity")
        resolved[claim] = identity
    if req.ppi is not None:
        selected = resolved[req.ppi]
    elif req.from_uri != ANON:
        selected = resolved[req.from_uri]
    else:
        selected = policy.accounts[subject]["primary"]
    if not policy.allowed(subject, selected):
        raise Reject("identity")
    if not policy.hosted(gateway, selected):
        raise Reject("identity")
    return selected, "local"


def decide_peer(req, policy, gateway, peer):
    peers = policy.gateways[gateway]["peers"]
    if peer not in peers:
        raise Reject("unauthenticated")
    if not req.pai:
        raise Reject("unauthenticated")
    authority = peers[peer]
    selected = None
    for claim in req.pai:
        identity = policy.resolve(claim)
        if identity is None:
            raise Reject("identity")
        if selected is None:
            selected = identity
        elif identity != selected:
            raise Reject("identity")
    if policy.domain.get(selected) not in authority:
        raise Reject("identity")
    claims = []
    if req.from_uri != ANON:
        claims.append(req.from_uri)
    if req.ppi is not None:
        claims.append(req.ppi)
    if req.rpid is not None:
        claims.append(req.rpid)
    for claim in claims:
        if policy.resolve(claim) != selected:
            raise Reject("identity")
    return selected, "peer"


def evaluate(req, policy, gateway, ingress, trusted_out):
    kind = ingress.get("kind")
    if kind == "local":
        selected, basis = decide_local(req, policy, gateway, ingress.get("subject"))
    elif kind == "peer":
        selected, basis = decide_peer(req, policy, gateway, ingress.get("name"))
    else:
        raise Reject("unauthenticated")
    private = (req.from_uri == ANON) or (req.privacy == "id")
    emit_pai = (not private) or bool(trusted_out)
    wire = build_wire(req, selected, private, emit_pai)
    return {
        "status": "accept",
        "identity": selected,
        "basis": basis,
        "private": private,
        "wire": wire,
    }


# --------------------------------------------------------------------------
# Batch driver
# --------------------------------------------------------------------------

def run_job(job, policy, results):
    if "raw" in job:
        text = job["raw"]
        if not isinstance(text, str):
            syntax()
    else:
        source = job.get("source")
        if not isinstance(source, int) or isinstance(source, bool):
            raise Reject("upstream")
        if source < 0 or source >= len(results):
            raise Reject("upstream")
        previous = results[source]
        if previous.get("status") != "accept":
            raise Reject("upstream")
        text = previous["wire"]
    gateway = job["gateway"]
    req = parse_request(text)
    return evaluate(req, policy, gateway, job["ingress"], job["trusted_out"])


def process(batch):
    policy = Policy(batch.get("directory") or {}, batch.get("accounts") or {},
                    batch.get("gateways") or {})
    results = []
    for job in batch.get("jobs") or []:
        try:
            results.append(run_job(job, policy, results))
        except Reject as exc:
            results.append({"status": "reject", "reason": exc.reason})
        except Exception:  # pragma: no cover - defensive only
            results.append({"status": "reject", "reason": "syntax"})
    return {"results": results}


def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:  # pragma: no cover - defensive only
        data = b""
    try:
        batch = json.loads(data.decode("utf-8"))
    except Exception:
        batch = None
    if isinstance(batch, dict):
        try:
            output = process(batch)
        except Exception:  # pragma: no cover - defensive only
            output = {"results": []}
    else:
        output = {"results": []}
    sys.stdout.write(json.dumps(output))
    sys.stdout.write("\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
